export function initSocials(){
 const el=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const num=v=>v===null||v===undefined?'—':new Intl.NumberFormat('cs-CZ').format(v);
 let handle='',part='profile',revision=0,status=null;const results=new Map();
 const projectDefaults={endpointMode:'curated',feedTimeframe:'D7',changesTimeframe:'H24',orderBy:'SCORE',orderByDirection:'DESC',limit:10,offset:0};
 let projectFilters={...projectDefaults},projectBusy=false,projectOptions={chains:[],tags:[]};
 async function api(path,body){const r=await fetch('/api/socials/moni/'+path,{...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok)throw Error(data.error||'Moni se nepodařilo načíst.');return data;}
 function usage(value){if(value)status=value.month===status?.month?{...value,estimatedPoints:Math.max(value.estimatedPoints,status.estimatedPoints)}:value;el('moni-budget').textContent=status?`Odhad aplikace tento měsíc: ${num(status.estimatedPoints)} / ${num(status.monthlyBudget)} bodů místního rozpočtu. Nejde o zůstatek účtu Moni.`:'';}
 function readProjectPreferences(){try{const saved=JSON.parse(localStorage.getItem('moni-project-preferences')||'{}');projectFilters={...projectDefaults,...saved};}catch{projectFilters={...projectDefaults};}for(const [key,id] of Object.entries({endpointMode:'moni-project-mode',feedTimeframe:'moni-project-feed-timeframe',changesTimeframe:'moni-project-changes-timeframe',orderBy:'moni-project-order-by',orderByDirection:'moni-project-order-direction'})){if(el(id))el(id).value=projectFilters[key]||projectDefaults[key];}for(const [key,id] of Object.entries({excludeChains:'moni-project-exclude-chains',excludeTags:'moni-project-exclude-tags',minSmartFollowersCount:'moni-project-min-smart-followers',maxSmartFollowersCount:'moni-project-max-smart-followers',minFollowersCount:'moni-project-min-followers',maxFollowersCount:'moni-project-max-followers',minMlProjectPredictionPercents:'moni-project-min-ml',maxMlProjectPredictionPercents:'moni-project-max-ml',showOnlyContracts:'moni-project-contracts',showOnlyPublic:'moni-project-public'}))if(el(id))el(id).value=projectFilters[key]??'';if(el('moni-project-raw-contracts'))el('moni-project-raw-contracts').value=projectFilters.showOnlyContracts??'';renderProjectPickers();syncProjectMode();}
 function projectQueryObject(){const mode=el('moni-project-mode').value||'curated',q={endpointMode:mode,feedTimeframe:el('moni-project-feed-timeframe').value,changesTimeframe:el('moni-project-changes-timeframe').value,orderBy:el('moni-project-order-by').value,orderByDirection:el('moni-project-order-direction').value,limit:10,offset:Number(projectFilters.offset)||0};if(mode==='curated'){for(const key of ['chains','tags'])if((projectFilters[key]||[]).length)q[key]=[...projectFilters[key]].sort();for(const [key,id] of Object.entries({excludeChains:'moni-project-exclude-chains',excludeTags:'moni-project-exclude-tags',minSmartFollowersCount:'moni-project-min-smart-followers',maxSmartFollowersCount:'moni-project-max-smart-followers',minFollowersCount:'moni-project-min-followers',maxFollowersCount:'moni-project-max-followers',showOnlyContracts:'moni-project-contracts',showOnlyPublic:'moni-project-public'})){const value=el(id).value;if(value!=='')q[key]=['minSmartFollowersCount','maxSmartFollowersCount','minFollowersCount','maxFollowersCount'].includes(key)?Number(value):value;}}else for(const [key,id] of Object.entries({minMlProjectPredictionPercents:'moni-project-min-ml',maxMlProjectPredictionPercents:'moni-project-max-ml',showOnlyContracts:'moni-project-raw-contracts'})){const value=el(id).value;if(value!=='')q[key]=key.startsWith('minMl')||key.startsWith('maxMl')?Number(value):value;}return q;}
 function projectQuery(){return new URLSearchParams(Object.entries(projectQueryObject()).map(([k,v])=>[k,Array.isArray(v)?v.join(','):String(v)])).toString();}
 function saveProjectPreferences(){projectFilters=projectQueryObject();try{localStorage.setItem('moni-project-preferences',JSON.stringify(projectFilters));}catch{}renderProjectChips();}
 function projectChanged(){projectFilters.offset=0;saveProjectPreferences();showProjectCache();}
 function renderProjectPickers(){for(const key of ['chains','tags']){const chosen=projectFilters[key]||[],options=projectOptions[key]||[];const label=key==='chains'?'sítí':'kategorií';const toggle=document.querySelector(`[data-picker-toggle="${key}"]`);if(toggle)toggle.textContent=chosen.length?`${chosen.length} ${label}`:`Všechny ${label}`;const list=document.querySelector(`[data-picker-options="${key}"]`);if(list){const search=document.querySelector(`[data-picker-search="${key}"]`)?.value.toLowerCase()||'';const rows=options.filter(o=>(o.name+' '+o.slug).toLowerCase().includes(search));list.innerHTML=rows.map(o=>`<label class="moni-picker-option"><input type="checkbox" data-pick="${key}" value="${esc(o.slug)}" ${chosen.includes(o.slug)?'checked':''}><span>${esc(o.name)}</span><small>${esc(o.slug)}</small></label>`).join('')||'<small class="socials-footnote">Seznam možností není dostupný.</small>';}}}
 function syncProjectMode(){const raw=el('moni-project-mode').value==='raw';el('moni-curated-fields').hidden=raw;el('moni-curated-engagement').hidden=raw;el('moni-raw-fields').hidden=!raw;}
 function renderProjectChips(){const box=el('moni-project-active-filters');const q=projectQueryObject(),labels=[];for(const key of ['chains','tags'])for(const value of q[key]||[])labels.push([key,value,value]);for(const [key,name,suffix] of [['minSmartFollowersCount','Smart Followers ≥',''],['maxSmartFollowersCount','Smart Followers ≤',''],['minFollowersCount','Followers ≥',''],['maxFollowersCount','Followers ≤',''],['minMlProjectPredictionPercents','ML ≥',' %'],['maxMlProjectPredictionPercents','ML ≤',' %']])if(q[key]!==undefined)labels.push([key,`${name} ${num(q[key])}${suffix}`,'']);for(const [key,label] of [['showOnlyContracts','Contracts'],['showOnlyPublic','Veřejné']])if(q[key]!==undefined)labels.push([key,`${label}: ${q[key]==='true'?'ano':'ne'}`,'']);for(const [key,label] of [['excludeTags','Vyloučené kategorie'],['excludeChains','Vyloučené sítě']])if(q[key])for(const value of q[key].split(','))labels.push([key,`${label}: ${value}`,value]);box.innerHTML=labels.map(([key,label,value])=>`<button class="moni-filter-chip" data-remove-filter="${esc(key)}" data-value="${esc(value)}">${esc(label)} ×</button>`).join('')+(labels.length?'<button class="subtle-button" id="moni-project-clear-advanced">Vymazat filtry</button>':'');el('moni-project-advanced-toggle').textContent=`Pokročilé filtry${labels.length?` (${labels.length})`:''}`;}
 function projectDelta(value,period){if(value===null||value===undefined)return '';const n=num(value),cls=value>0?'positive':value<0?'negative':'';return `<span class="moni-change ${cls}">${value>0?'+':''}${n} / ${esc(period)}</span>`;}
 function renderProjects(result){usage(result.usage);const stale=result.cacheStatus==='stale'||result.stale;const freshAt=result.fetchedAt?new Date(result.fetchedAt).toLocaleString('cs-CZ'):'';el('moni-project-meta').textContent=result.cacheStatus==='missing'?'Tato kombinace ještě není načtená. Změna filtrů nic nenačítá.':`${stale?'Zastaralá data':'Uložená data'} · ${freshAt} · ${projectFilters.endpointMode==='raw'?'Raw':'Curated'} · řazeno podle ${el('moni-project-order-by').selectedOptions[0].text}`;el('moni-project-load').textContent=result.cacheStatus==='missing'?'Načíst z Moni · až 10 bodů':'Obnovit · až 10 bodů';const items=result.data?.items||[];const fmtDate=value=>value&&Number.isFinite(Date.parse(value))?new Date(value).toLocaleDateString('cs-CZ'):'—';el('moni-projects').innerHTML=items.map(x=>`<tr><td><strong>@${esc(x.handle)}</strong><small>${fmtDate(x.createdAt)}</small></td><td>${num(x.score)}</td><td>${num(x.smartsCount)}</td><td>${num(x.smartMentionsCount)}</td><td>${x.smartMentionsChange===null?'—':`${x.smartMentionsChange>0?'+':''}${num(x.smartMentionsChange)}`}</td><td>${num(x.followersCount)}</td><td>${esc(x.chains.join(', ')||'—')}</td><td>${esc(x.categories.join(', ')||'—')}</td></tr>`).join('')||'<tr><td colspan="8">Moni pro tento filtr nevrátilo projekty.</td></tr>';const page=(Number(projectFilters.offset)||0)/10+1;el('moni-project-page').textContent=`Strana ${page} · ${result.cacheStatus==='missing'?'bez cache':''}`;el('moni-project-prev').disabled=page<=1;el('moni-project-next').disabled=items.length<10;el('moni-project-load').disabled=!status?.configured||projectBusy;renderProjectChips();}
 async function showProjectCache(){try{const result=await fetch('/api/socials/moni/projects?'+projectQuery()).then(async r=>{const d=await r.json();if(!r.ok)throw Error(d.error||'Cache Moni nelze načíst.');return d;});if(projectFilters.endpointMode==='raw'&&result.cacheStatus==='missing')result.cacheStatus='missing';renderProjects(result);}catch(error){el('moni-project-meta').textContent=error.message;}}
 async function show(){
  if(location.protocol==='file:'){el('moni-status').textContent='Moni vyžaduje lokální server';el('moni-search-button').disabled=true;return;}
  refreshWatchlist();
  readProjectPreferences();try{const s=await api('status');usage(s);el('moni-status').textContent=s.configured?'Moni · klíč nastavený':'Moni · chybí serverový klíč';el('moni-search-button').disabled=!s.configured;el('moni-project-load').disabled=!s.configured;if(s.configured){const options=await fetch('/api/socials/moni/project-options').then(r=>r.json());projectOptions=options.available?options:{chains:[],tags:[]};renderProjectPickers();}await showProjectCache();}catch{el('moni-status').textContent='Lokální server není dostupný';}
 }
 function render(result){
  usage(result.usage);el('moni-status').textContent='Moni · připojeno';
  el('moni-meta').textContent=`@${result.handle} · ${result.cached?'Uložená data':'Načteno z Moni'} · ${new Date(result.fetchedAt).toLocaleString('cs-CZ')} · platnost cache do ${new Date(result.expiresAt).toLocaleString('cs-CZ')}`;
  const d=result.data;
  if(result.part==='profile')el('moni-result').innerHTML=`<div class="moni-profile"><div><span class="eyebrow">PROFIL ÚČTU</span><h2>@${esc(result.handle)}</h2>${d.url?`<a href="${esc(d.url)}" target="_blank" rel="noopener noreferrer">Otevřít profil na X ↗</a>`:''}<div class="smart-tags">${[...d.tags,...d.categories,...d.chains].map(t=>`<span>${esc(t)}</span>`).join('')}</div></div><div class="moni-metrics">${[['Moni Score',d.score],['Smarts',d.smartsCount],['Smart Mentions',d.smartMentionsCount],['Všechny zmínky',d.mentionsCount]].map(([title,n])=>`<div><span>${title}</span><strong>${num(n)}</strong></div>`).join('')}</div></div><p class="socials-footnote">Skóre a počty dodává Moni. Vyjadřují sociální kontext, nikoli ziskovost peněženky. Historické počty nejsou omezené na posledních 7 dní.</p>`;
  else if(result.part==='mentions')el('moni-result').innerHTML=`<h2>Smart Mentions · posledních 7 dní</h2><p class="socials-footnote">Nejvýše 20 posledních zmínek účtu @${esc(result.handle)}. Moni vrací odkazy na příspěvky; jejich text zde nenačítáme.</p>${d.items.length?d.items.map(row=>`<div class="moni-list-row"><strong>${esc(row.authorUrl?new URL(row.authorUrl).pathname.slice(1):'Účet na X')}</strong><span>${row.at?esc(new Date(row.at*1000).toLocaleString('cs-CZ')):'Datum není dostupné'}</span>${row.postUrl?`<a href="${esc(row.postUrl)}" target="_blank" rel="noopener noreferrer">Otevřít příspěvek ↗</a>`:'<span>Odkaz není dostupný</span>'}</div>`).join(''):'<p>Moni pro toto období nevrátilo žádné zmínky.</p>'}`;
  else el('moni-result').innerHTML=`<h2>Významní sledující · Smarts</h2><p class="socials-footnote">Zobrazeno ${d.items.length}${d.total!==null?' z '+num(d.total):''}. První stránka podle pořadí Moni, nejvýše 20 účtů.</p>${d.items.length?d.items.map(row=>`<div class="moni-list-row"><strong>@${esc(row.handle)}</strong><span>Moni Score ${num(row.score)} · ${num(row.smartsCount)} Smarts</span>${row.url?`<a href="${esc(row.url)}" target="_blank" rel="noopener noreferrer">Profil na X ↗</a>`:''}</div>`).join(''):'<p>Moni nevrátilo žádné významné sledující.</p>'}`;
 }
 async function load(nextPart){
  if(!handle)return;
  part=nextPart;const current=++revision,requested=handle;
  el('moni-error').hidden=true;el('moni-meta').textContent='';
  document.querySelectorAll('[data-moni-part]').forEach(b=>{b.classList.toggle('active',b.dataset.moniPart===part);b.setAttribute('aria-selected',String(b.dataset.moniPart===part));});
  el('moni-result').innerHTML='<p role="status">Načítám data z Moni…</p>';
  const key=handle+':'+part,cached=results.get(key);
  try{
   const result=cached&&Date.parse(cached.expiresAt)>Date.now()?cached:await api('account',{handle:requested,part:nextPart});
   results.set(key,result);if(current!==revision)return;
   render(result);
  }catch(error){if(current!==revision)return;el('moni-result').innerHTML='';el('moni-error').textContent=error.message;el('moni-error').hidden=false;show();}
 }
 el('moni-form').addEventListener('submit',event=>{
  event.preventDefault();const input=el('moni-handle').value.trim().replace(/^@/,'');
  if(!/^[a-z0-9_]{1,15}$/i.test(input)){el('moni-error').textContent='Zadejte @handle účtu na X, ne adresu kontraktu.';el('moni-error').hidden=false;return;}
  handle=input.toLowerCase();el('moni-tabs').hidden=false;load('profile');
 });
 el('socials-section').addEventListener('click',event=>{const button=event.target.closest('[data-moni-part]');if(button)load(button.dataset.moniPart);});
 async function watchApi(method='GET',handle=''){
  const r=await fetch('/api/socials/watchlist'+(method==='DELETE'?'/'+encodeURIComponent(handle):''),{method,...(method==='POST'?{headers:{'Content-Type':'application/json'},body:JSON.stringify({handle})}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'Seznam nelze uložit.');return d.items;
 }
 function drawWatchlist(items){el('moni-watchlist').innerHTML=items.length?items.map(x=>'<div class="moni-list-row"><strong>@'+esc(x.handle)+'</strong><button class="subtle-button" data-open-account="'+esc(x.handle)+'">Profil · 8 bodů</button><button class="subtle-button" data-remove-account="'+esc(x.handle)+'">Odebrat</button></div>').join(''):'<p class="socials-footnote">Zatím nesledujete žádný účet.</p>';}
 async function refreshWatchlist(){try{drawWatchlist(await watchApi());}catch(e){el('moni-watch-error').textContent=e.message;}}
 async function saveWatch(value){try{drawWatchlist(await watchApi('POST',value));el('moni-watch-input').value='';el('moni-watch-error').textContent='';}catch(e){el('moni-watch-error').textContent=e.message;}}
 el('moni-watch-form').addEventListener('submit',e=>{e.preventDefault();saveWatch(el('moni-watch-input').value);});
 el('socials-section').addEventListener('click',async e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.dataset.openAccount){handle=b.dataset.openAccount.toLowerCase();el('moni-handle').value='@'+handle;el('moni-tabs').hidden=false;load('profile');}
  if(b.dataset.watchAccount)saveWatch(b.dataset.watchAccount);
  if(b.dataset.removeAccount){b.disabled=true;try{drawWatchlist(await watchApi('DELETE',b.dataset.removeAccount));}catch(e){el('moni-watch-error').textContent=e.message;b.disabled=false;}}
 });
 for(const id of ['moni-project-mode','moni-project-feed-timeframe','moni-project-changes-timeframe','moni-project-order-by','moni-project-order-direction'])el(id).addEventListener('change',()=>{syncProjectMode();projectChanged();});
 for(const id of ['moni-project-exclude-chains','moni-project-exclude-tags','moni-project-min-smart-followers','moni-project-max-smart-followers','moni-project-min-followers','moni-project-max-followers','moni-project-min-ml','moni-project-max-ml','moni-project-contracts','moni-project-public','moni-project-raw-contracts'])el(id).addEventListener('change',projectChanged);
 el('moni-project-advanced-toggle').addEventListener('click',()=>{const open=el('moni-project-advanced').hidden;el('moni-project-advanced').hidden=!open;el('moni-project-advanced-toggle').setAttribute('aria-expanded',String(open));});
 document.querySelectorAll('[data-picker-toggle]').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();const menu=button.parentElement.querySelector('.moni-picker-menu'),open=menu.hidden;document.querySelectorAll('.moni-picker-menu').forEach(x=>x.hidden=true);menu.hidden=!open;}));
 document.addEventListener('click',event=>{if(!event.target.closest('.moni-picker'))document.querySelectorAll('.moni-picker-menu').forEach(x=>x.hidden=true);});
 document.querySelectorAll('[data-picker-search]').forEach(input=>input.addEventListener('input',()=>renderProjectPickers()));
 el('moni-project-advanced').addEventListener('change',event=>{const input=event.target.closest('[data-pick]');if(!input)return;const key=input.dataset.pick;const values=new Set(projectFilters[key]||[]);input.checked?values.add(input.value):values.delete(input.value);projectFilters[key]=[...values].sort();renderProjectPickers();projectChanged();});
 el('moni-project-active-filters').addEventListener('click',event=>{const remove=event.target.closest('[data-remove-filter]');if(remove){const key=remove.dataset.removeFilter,value=remove.dataset.value;if(key==='chains'||key==='tags')projectFilters[key]=(projectFilters[key]||[]).filter(x=>x!==value);else if(key==='excludeChains'||key==='excludeTags'){const id=key==='excludeChains'?'moni-project-exclude-chains':'moni-project-exclude-tags';el(id).value=el(id).value.split(',').map(x=>x.trim()).filter(x=>x&&x!==value).join(',');}else{const id={minSmartFollowersCount:'moni-project-min-smart-followers',maxSmartFollowersCount:'moni-project-max-smart-followers',minFollowersCount:'moni-project-min-followers',maxFollowersCount:'moni-project-max-followers',minMlProjectPredictionPercents:'moni-project-min-ml',maxMlProjectPredictionPercents:'moni-project-max-ml',showOnlyContracts:projectFilters.endpointMode==='raw'?'moni-project-raw-contracts':'moni-project-contracts',showOnlyPublic:'moni-project-public'}[key];if(id)el(id).value='';}renderProjectPickers();projectChanged();}if(event.target.id==='moni-project-clear-advanced')clearAdvanced();});
 function clearAdvanced(){projectFilters.chains=[];projectFilters.tags=[];for(const id of ['moni-project-exclude-chains','moni-project-exclude-tags','moni-project-min-smart-followers','moni-project-max-smart-followers','moni-project-min-followers','moni-project-max-followers','moni-project-min-ml','moni-project-max-ml','moni-project-contracts','moni-project-public','moni-project-raw-contracts'])el(id).value='';renderProjectPickers();projectChanged();}
 el('moni-project-reset').addEventListener('click',()=>{projectFilters={...projectDefaults};for(const [key,id] of Object.entries({endpointMode:'moni-project-mode',feedTimeframe:'moni-project-feed-timeframe',changesTimeframe:'moni-project-changes-timeframe',orderBy:'moni-project-order-by',orderByDirection:'moni-project-order-direction'}))el(id).value=projectDefaults[key];clearAdvanced();});
 const builtInPresets={'top-score':{...projectDefaults,orderBy:'SCORE',orderByDirection:'DESC'},growing:{...projectDefaults,orderBy:'SMART_FOLLOWERS_COUNT_CHANGE',orderByDirection:'DESC'},'smart-activity':{...projectDefaults,orderBy:'SMART_MENTIONS_COUNT_CHANGE',orderByDirection:'DESC'},'new-projects':{...projectDefaults,orderBy:'CREATED_AT',orderByDirection:'DESC'}};
 function refreshPresetOptions(){const select=el('moni-project-preset'),custom=(()=>{try{return JSON.parse(localStorage.getItem('moni-project-presets')||'{}');}catch{return {};}})();select.querySelectorAll('[data-custom-preset]').forEach(x=>x.remove());for(const [name] of Object.entries(custom)){const option=document.createElement('option');option.value=`custom:${name}`;option.textContent=name;option.dataset.customPreset='1';select.append(option);}}
 refreshPresetOptions();el('moni-project-preset').addEventListener('change',()=>{const value=el('moni-project-preset').value;if(!value)return;let preset=builtInPresets[value];if(value.startsWith('custom:')){try{preset=JSON.parse(localStorage.getItem('moni-project-presets')||'{}')[value.slice(7)];}catch{}}if(!preset)return;projectFilters={...projectDefaults,...preset,offset:0};try{localStorage.setItem('moni-project-preferences',JSON.stringify(projectFilters));}catch{}readProjectPreferences();saveProjectPreferences();syncProjectMode();showProjectCache();el('moni-project-preset').value='';});
 el('moni-project-save-preset').addEventListener('click',()=>{const name=prompt('Název lokálního presetu:');if(!name?.trim())return;try{const presets=JSON.parse(localStorage.getItem('moni-project-presets')||'{}');presets[name.trim().slice(0,40)]=projectQueryObject();localStorage.setItem('moni-project-presets',JSON.stringify(presets));refreshPresetOptions();el('moni-project-meta').textContent=`Preset „${name.trim().slice(0,40)}“ uložen pouze v tomto prohlížeči.`;}catch{el('moni-project-meta').textContent='Preset se nepodařilo uložit.';}});
 el('moni-project-prev').addEventListener('click',()=>{projectFilters.offset=Math.max(0,(Number(projectFilters.offset)||0)-10);saveProjectPreferences();showProjectCache();});el('moni-project-next').addEventListener('click',()=>{projectFilters.offset=(Number(projectFilters.offset)||0)+10;saveProjectPreferences();showProjectCache();});
 document.querySelectorAll('[data-project-sort]').forEach(button=>button.addEventListener('click',()=>{const order=button.dataset.projectSort,current=projectQueryObject();el('moni-project-order-direction').value=current.orderBy===order&&current.orderByDirection==='DESC'?'ASC':'DESC';el('moni-project-order-by').value=order;projectChanged();}));
 el('moni-project-load').addEventListener('click',async()=>{if(projectBusy||!status?.configured)return;projectBusy=true;el('moni-project-load').disabled=true;el('moni-project-meta').textContent='Načítám vybranou kombinaci z Moni…';try{const query=projectQueryObject(),r=await api('projects',{query});usage(r.usage);renderProjects({...r,cacheStatus:'fresh'});}catch(e){el('moni-project-meta').textContent=e.message;}finally{projectBusy=false;el('moni-project-load').disabled=!status?.configured;}});
 return {show};
}
